import {distance,routeLength,matchOSM} from './geo.js?v=2.1.1';
const $=id=>document.getElementById(id);
const setHidden=(id,value)=>{const element=$(id);if(element)element.hidden=value;};
let trace=[],selected=[],gpsSelection=[],records=[],rides=[],first=null,last=null,rating=0,mode='auto',snapped=false,busy=false,view='explore',currentRide=null,map,routeLayer,selectionLayer,marks,snapController,snapVersion=0;
const winterLabels={unknown:'Hiver non renseigné',yes:'Roulable en hiver',no:'Non roulable en hiver',conditions:'Hiver selon conditions'};
async function api(path,options={}){const res=await fetch(path,{...options,headers:{'Content-Type':'application/json',...options.headers}});if(res.status===401){location.replace('/login.html');throw Error('Session expirée.');}const data=await res.json();if(!res.ok)throw Error(data.error||'Le serveur ne répond pas.');return data;}
const post=(path,data,options={})=>api(path,{method:'POST',body:JSON.stringify(data),...options});
function toast(t){$('toast').textContent=t;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',6000);}
function status(t){$('status').textContent=t;}
function stars(){ $('stars').replaceChildren();for(let i=1;i<=5;i++){const b=document.createElement('button');b.type='button';b.textContent='★';b.className=i<=rating?'on':'';b.setAttribute('aria-label',`${i} sur 5`);b.setAttribute('aria-pressed',String(rating===i));b.onclick=()=>{rating=i;stars();update();};$('stars').append(b);}}
function update(){
 $('distance').innerHTML=selected.length>1?`${(routeLength(selected)/1000).toFixed(2)} <em>km</em>`:'— <em>km</em>';
 $('snapState').textContent=busy?'OSM en cours…':snapped?'OSM · à vérifier':mode==='manual'?'Manuel':'GPS d’origine';
 $('save').disabled=selected.length<2||!rating||busy||view!=='explore';$('snap').disabled=!gpsSelection.length||busy;setHidden('snap',mode==='manual'||view==='saved');setHidden('undo',mode!=='manual'||view==='saved');$('undo').disabled=!selected.length;
 $('count').textContent=records.length;$('autoMode').classList.toggle('active',mode==='auto');$('manualMode').classList.toggle('active',mode==='manual');
}
function cancelSnap(){snapVersion++;snapController?.abort();busy=false;}
function reset(){cancelSnap();selected=[];gpsSelection=[];first=last=null;snapped=false;rating=0;$('ratingForm').reset();status(mode==='manual'?'Cliquez sur la carte pour tracer point à point.':'Choisissez un départ et une arrivée sur la trace GPX.');drawSelection();stars();update();}
function drawSelection(){if(!map)return;selectionLayer.clearLayers();marks.clearLayers();if(selected.length){if(selected.length>1){L.polyline(selected,{pane:'portionPane',color:'#fff8df',weight:10,opacity:1,interactive:false}).addTo(selectionLayer);L.polyline(selected,{pane:'portionPane',color:'#d28a24',weight:6,opacity:1,interactive:false}).addTo(selectionLayer);}for(const[i,p]of selected.entries()){if(mode!=='manual'&&i!==0&&i!==selected.length-1)continue;L.marker(p,{pane:'markerPane',icon:L.divIcon({className:'endpoint',iconSize:[15,15]})}).bindTooltip(i===0?'Départ':i===selected.length-1?'Arrivée':`Point ${i+1}`).addTo(marks);}}}
function fit(points=trace){if(map)map.invalidateSize({pan:false});if(map&&points.length>1)map.fitBounds(L.latLngBounds(points),{paddingTopLeft:[30,30],paddingBottomRight:[innerWidth>850?370:30,40]});}
function drawRoute(){if(!map)return;routeLayer.clearLayers();if(!trace.length)return;L.polyline(trace,{pane:'gpxPane',color:'#fff',weight:9,opacity:.9}).addTo(routeLayer);L.polyline(trace,{pane:'gpxPane',color:'#496975',weight:5,opacity:.85}).addTo(routeLayer).on('click',e=>{L.DomEvent.stopPropagation(e);choose(e.latlng);});fit();}
function choose(latlng){if(view!=='explore')return;if(mode==='manual'){cancelSnap();selected.push([latlng.lat,latlng.lng]);snapped=false;drawSelection();status('Tracé manuel en segments droits. Ajoutez des points pour suivre le chemin.');update();return;}if(!trace.length)return toast('Importez un GPX ou choisissez le mode manuel.');if(busy)return;
 let idx=0,best=Infinity;trace.forEach((p,i)=>{const d=distance(p,[latlng.lat,latlng.lng]);if(d<best){idx=i;best=d;}});if(best>200)return toast('Cliquez plus près de la trace GPX.');
 if(first===null||last!==null){reset();first=idx;selected=[trace[idx]];drawSelection();status('Départ posé. Choisissez l’arrivée.');}
 else{if(idx===first)return toast('Choisissez une arrivée différente.');last=idx;gpsSelection=trace.slice(Math.min(first,last),Math.max(first,last)+1);selected=gpsSelection.map(p=>[...p]);drawSelection();void snap();}update();
}
async function snap(){
 if(gpsSelection.length<2)return;cancelSnap();const version=snapVersion;snapped=false;selected=gpsSelection.map(p=>[...p]);drawSelection();if(routeLength(gpsSelection)>15000){status('Accrochage limité à 15 km. Réduisez la portion ou passez en manuel.');update();return;}
 busy=true;update();status('Accrochage automatique aux chemins OpenStreetMap…');snapController=new AbortController();
 try{const lat=gpsSelection.map(p=>p[0]),lon=gpsSelection.map(p=>p[1]);const data=await post('/api/osm',{bbox:[Math.min(...lat)-.002,Math.min(...lon)-.003,Math.max(...lat)+.002,Math.max(...lon)+.003]},{signal:snapController.signal});if(version!==snapVersion)return;selected=matchOSM(gpsSelection,data.elements||[]);snapped=true;drawSelection();status('Tracé OSM en orange au-dessus du GPX bleu. Vérifiez-le avant d’enregistrer.');}
 catch(e){if(version!==snapVersion)return;status(`Accrochage impossible : ${e.message} Le GPS reste visible ; le mode manuel est disponible.`);}
 finally{if(version===snapVersion){busy=false;update();}}
}
function setMode(next){if(next===mode)return;cancelSnap();mode=next;snapped=false;if(mode==='manual'){selected=selected.length>1?[selected[0],selected.at(-1)]:selected;status('Mode manuel : ajoutez des points sur la carte. Annulez le dernier point si nécessaire.');}else{selected=[];gpsSelection=[];first=last=null;status('Choisissez deux points sur le GPX pour l’accrochage automatique.');}drawSelection();update();}
if(typeof L!=='undefined'){
 map=L.map('map',{zoomControl:false}).setView([50.49,5.86],11);map.createPane('gpxPane');map.getPane('gpxPane').style.zIndex=410;map.createPane('portionPane');map.getPane('portionPane').style.zIndex=450;
 const osm=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{updateWhenIdle:true,keepBuffer:3,referrerPolicy:'strict-origin-when-cross-origin',attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>',maxZoom:19}).addTo(map);
 const satellite=L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',{attribution:'Tiles © Esri — Source: Esri, Maxar, Earthstar Geographics, and the GIS User Community',maxZoom:19});
 L.control.layers({'OpenStreetMap':osm,'Satellite · Esri':satellite},null,{position:'topleft'}).addTo(map);L.control.zoom({position:'topleft'}).addTo(map);
 const notice=$('mapNotice');let failures=0;
 const showNotice=message=>{if(notice){notice.textContent=message;notice.hidden=false;}};
 osm.on('tileerror',()=>{if(!map.hasLayer(osm))return;if(++failures>=3)showNotice('Certaines tuiles OSM ne se chargent pas. Vous pouvez choisir Satellite dans le sélecteur de couches.');});
 osm.on('loading',()=>{failures=0;});
 osm.on('load',()=>{if(failures===0)setHidden('mapNotice',true);});
 satellite.on('tileerror',()=>{if(map.hasLayer(satellite))showNotice('Certaines images satellite sont indisponibles. Vous pouvez revenir à OpenStreetMap.');});
 map.on('baselayerchange',()=>{failures=0;setHidden('mapNotice',true);map.invalidateSize({pan:false});});
 if(typeof ResizeObserver!=='undefined')new ResizeObserver(()=>map.invalidateSize({pan:false})).observe($('map'));
 routeLayer=L.layerGroup().addTo(map);selectionLayer=L.layerGroup().addTo(map);marks=L.layerGroup().addTo(map);map.on('click',e=>choose(e.latlng));$('mapFallback').remove();
}else $('mapFallback').textContent='Carte indisponible : vérifiez votre connexion Internet puis rechargez.';
async function loadRide(id){const ride=await api(`/api/rides/${id}`);reset();currentRide=ride;trace=ride.coordinates;setView('explore');$('mapSubtitle').textContent=ride.name;drawRoute();renderRides();}
function renderRides(){const list=$('rideList');list.replaceChildren();if(!rides.length){const p=document.createElement('p');p.className='empty';p.textContent='Aucune sortie. Importez votre premier GPX.';list.append(p);}for(const r of rides){const b=document.createElement('button');b.className='ridebutton'+(currentRide?.id===r.id?' chosen':'');const title=document.createElement('strong'),small=document.createElement('small');title.textContent=r.name;small.textContent=`${(r.distance/1000).toFixed(1)} km`;b.append(title,small);b.onclick=()=>loadRide(r.id).catch(e=>toast(e.message));const row=document.createElement('div'),download=document.createElement('a');row.className='riderow';download.className='ridedownload';download.textContent='↓ GPX';download.href=`/api/rides/${r.id}/gpx`;download.title=r.gpx_available?'Télécharger le GPX original':'Télécharger la trace GPX reconstruite';row.append(b,download);list.append(row);}}
function parseGPX(xml){if(xml.querySelector('parsererror'))throw Error('GPX invalide.');const segments=[...xml.getElementsByTagNameNS('*','trkseg')];const read=(root,tag)=>[...root.getElementsByTagNameNS('*',tag)].filter(p=>p.hasAttribute('lat')&&p.hasAttribute('lon')).map(p=>[Number(p.getAttribute('lat')),Number(p.getAttribute('lon'))]).filter(p=>p.every(Number.isFinite)&&Math.abs(p[0])<=90&&Math.abs(p[1])<=180);let points=(segments.length?segments:[xml]).map(s=>read(s,'trkpt')).sort((a,b)=>b.length-a.length)[0]||[];if(points.length<2)points=read(xml,'rtept');if(points.length<2||points.length>100000)throw Error('Le GPX doit contenir entre 2 et 100 000 points.');return {points,multi:segments.length>1};}
$('gpx').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>25*1024*1024)throw Error('GPX limité à 25 Mo.');const gpx=await f.text();const xml=new DOMParser().parseFromString(gpx,'application/xml');const {points,multi}=parseGPX(xml),name=xml.getElementsByTagNameNS('*','trk')[0]?.getElementsByTagNameNS('*','name')[0]?.textContent||f.name.replace(/\.gpx$/i,'');const ride=await post('/api/rides',{name,coordinates:points,gpx,fileName:f.name});rides=await api('/api/rides');await loadRide(ride.id);toast(multi?'Segment GPX le plus long enregistré (trace interrompue).':'Sortie enregistrée dans votre compte.');}catch(e){toast(e.message);}finally{e.target.value='';}};
$('ratingForm').onsubmit=async e=>{e.preventDefault();if(selected.length<2||!rating||busy)return;const b=$('save');b.disabled=true;try{await post('/api/portions',{name:$('name').value,rating,difficulty:$('difficulty').value,surface:$('surface').value,winter:$('winter').value,notes:$('notes').value,coordinates:selected,snapped,mode:mode==='manual'?'manual':'gps',source:currentRide?.name||'Tracé manuel'});records=await api('/api/portions');reset();renderList();toast('Portion enregistrée dans votre compte.');}catch(e){toast(e.message);update();}};
function renderList(){const list=$('savedList');list.replaceChildren();if(view!=='saved')return;if(!records.length){const p=document.createElement('p');p.className='empty';p.textContent='Votre carnet attend son premier chemin.';list.append(p);}for(const r of records){const div=document.createElement('div');div.className='saveditem';const name=document.createElement('strong'),meta=document.createElement('small'),winter=document.createElement('small'),notes=document.createElement('p'),show=document.createElement('button'),del=document.createElement('button');name.textContent=r.name;meta.textContent=`${'★'.repeat(r.rating)} · ${(r.distance/1000).toFixed(2)} km · ${r.surface}`;winter.textContent=`${r.difficulty} · ${winterLabels[r.winter]||winterLabels.unknown} · ${r.snapped?'OSM':r.mode==='manual'?'Manuel':'GPS'}`;notes.textContent=r.notes;show.textContent='Voir sur la carte ↗';show.onclick=()=>{selected=r.coordinates;snapped=r.snapped;drawSelection();fit(selected);status(`Consultation : ${r.name}`);update();};del.textContent='Supprimer';del.onclick=async()=>{if(!confirm(`Supprimer « ${r.name} » ?`))return;try{await api(`/api/portions/${r.id}`,{method:'DELETE'});records=records.filter(x=>x.id!==r.id);renderList();update();}catch(e){toast(e.message);}};div.append(name,meta,winter,notes,show,del);list.append(div);}}
function setView(v){view=v;$('explore').classList.toggle('active',v==='explore');$('savedTab').classList.toggle('active',v==='saved');setHidden('rideList',v==='saved');$('listTitle').textContent=v==='saved'?'Mes portions':'Vos sorties';setHidden('source',v==='saved');setHidden('ratingForm',v==='saved');setHidden('modeControls',v==='saved');renderList();update();}
$('autoMode').onclick=()=>setMode('auto');$('manualMode').onclick=()=>setMode('manual');$('undo').onclick=()=>{selected.pop();drawSelection();update();};$('snap').onclick=snap;$('reset').onclick=reset;
$('savedTab').onclick=()=>{reset();setView('saved');};$('explore').onclick=()=>{reset();setView('explore');drawRoute();};$('fit').onclick=()=>fit(view==='saved'&&selected.length?selected:trace);
$('export').onclick=()=>{if(!records.length)return toast('Aucune portion à exporter.');const data={type:'FeatureCollection',features:records.map(r=>({type:'Feature',geometry:{type:'LineString',coordinates:r.coordinates.map(p=>[p[1],p[0]])},properties:{...r,coordinates:undefined}}))};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/geo+json'})),a=document.createElement('a');a.href=url;a.download='sillage-portions.geojson';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('logout').onclick=async()=>{try{await post('/api/logout',{});location.replace('/login.html');}catch(e){toast(e.message);}};
if($('legacyImport'))$('legacyImport').onclick=async()=>{if(!confirm('Transférer les anciennes notes de ce navigateur vers le compte actuellement connecté ?'))return;try{const old=JSON.parse(localStorage.getItem('sillage-portions')||'[]');let imported=0;for(let i=0;i<old.length;i+=500){const result=await post('/api/import-legacy',old.slice(i,i+500));imported+=result.imported;}records=await api('/api/portions');renderList();update();toast(`${imported} portion(s) transférée(s). Les copies locales sont conservées.`);}catch(e){toast(e.message);}};
try{const me=await api('/api/me');$('username').textContent=me.username;[records,rides]=await Promise.all([api('/api/portions'),api('/api/rides')]);renderRides();renderList();try{setHidden('legacyImport',!JSON.parse(localStorage.getItem('sillage-portions')||'[]').length);}catch{}if(rides.length)await loadRide(rides[0].id);}catch(e){toast(e.message);}stars();update();
